-- Step 2: Validate the constraint (scans table with ShareUpdateExclusive lock, allows reads/writes)
ALTER TABLE users VALIDATE CONSTRAINT users_full_name_not_null;

-- Step 3: Set NOT NULL (instant in PG 12+ when validated CHECK exists)
ALTER TABLE users ALTER COLUMN full_name SET NOT NULL;

-- Step 4: Drop the temporary CHECK constraint
